static void DBDMA_run (DBDMA_channel *ch)

{

    int channel;



    for (channel = 0; channel < DBDMA_CHANNELS; channel++, ch++) {

            uint32_t status = be32_to_cpu(ch->regs[DBDMA_STATUS]);

            if (!ch->processing && (status & RUN) && (status & ACTIVE))

                channel_run(ch);

    }

}

AVStream *add_av_stream1(FFStream *stream, AVCodecContext *codec)

{

    AVStream *fst;



    fst = av_mallocz(sizeof(AVStream));

    if (!fst)

        return NULL;

    fst->priv_data = av_mallocz(sizeof(FeedData));

    memcpy(&fst->codec, codec, sizeof(AVCodecContext));


    stream->streams[stream->nb_streams++] = fst;

    return fst;

}

static int restore_sigcontext(CPUAlphaState *env,

                              struct target_sigcontext *sc)

{

    uint64_t fpcr;

    int i, err = 0;



    __get_user(env->pc, &sc->sc_pc);



    for (i = 0; i < 31; ++i) {

        __get_user(env->ir[i], &sc->sc_regs[i]);

    }

    for (i = 0; i < 31; ++i) {

        __get_user(env->fir[i], &sc->sc_fpregs[i]);

    }



    __get_user(fpcr, &sc->sc_fpcr);

    cpu_alpha_store_fpcr(env, fpcr);



    return err;

}

void kvm_arm_register_device(MemoryRegion *mr, uint64_t devid)

{

    KVMDevice *kd;



    if (!kvm_irqchip_in_kernel()) {

        return;

    }



    if (QSLIST_EMPTY(&kvm_devices_head)) {

        memory_listener_register(&devlistener, NULL);

        qemu_add_machine_init_done_notifier(&notify);

    }

    kd = g_new0(KVMDevice, 1);

    kd->mr = mr;

    kd->kda.id = devid;

    kd->kda.addr = -1;

    QSLIST_INSERT_HEAD(&kvm_devices_head, kd, entries);

    memory_region_ref(kd->mr);

}

static int add_doubles_metadata(int count,

                                const char *name, const char *sep,

                                TiffContext *s)

{

    char *ap;

    int i;

    double *dp;



    if (count >= INT_MAX / sizeof(int64_t) || count <= 0)

        return AVERROR_INVALIDDATA;

    if (bytestream2_get_bytes_left(&s->gb) < count * sizeof(int64_t))

        return AVERROR_INVALIDDATA;



    dp = av_malloc(count * sizeof(double));

    if (!dp)

        return AVERROR(ENOMEM);



    for (i = 0; i < count; i++)

        dp[i] = tget_double(&s->gb, s->le);

    ap = doubles2str(dp, count, sep);

    av_freep(&dp);

    if (!ap)

        return AVERROR(ENOMEM);

    av_dict_set(avpriv_frame_get_metadatap(&s->picture), name, ap, AV_DICT_DONT_STRDUP_VAL);

    return 0;

}

